if(!D.projV1){D.projects=[
 {id:'bahiram',n:'Bahiram',m:['darshan','nameera','swapnil','himanshu']},
 {id:'ops',n:'OPS LOGISTICS',m:['darshan','nameera','mohin','omadsul']},
 {id:'xenmag',n:'XENMAG',m:['darshan','nameera','swapnil','omparvate']},
 {id:'cse',n:'CSE-JDAC',m:['darshan','nameera','neetu','balaji','imran']},
 {id:'hr',n:'HR',m:['darshan','nameera','snehalb']},
 {id:'wh',n:'Warehouse Team',m:['darshan','nameera','zubair','abrar','mustafa','samadhan','shubham']},
 {id:'acc',n:'Accounts',m:['darshan','nameera','snehalz']},
 {id:'smm',n:'SMM',m:['darshan','nameera','swapnil','omparvate','himanshu']},
 {id:'gb',n:'GovaaBazaar',m:['darshan','nameera','atmaram','yogesh']}];
 const byTeam={CSE:'cse',Ops:'ops',Marketing:'smm',Warehouse:'wh',HR:'hr',Accounts:'acc',GovaaBazaar:'gb'};
 D.tasks.forEach(t=>{if(!t.proj){const tm=(P[t.o]||{}).team;t.proj=byTeam[tm]||(t.co==='studios'?'smm':t.co==='log'?'ops':t.co==='jup'?'wh':t.co==='hr'?'hr':'gb')}});
 D.projV1=1;save()}
const KCOL=[['todo','To do','#8A93A3'],['plan','Planning','#2F6BE0'],['stuck','Stuck','#E03A3E'],['done','Completed','#1F9D55']];
const colOf=t=>t.st==='Done'||t.st==='Review'?'done':t.st==='Stuck'?'stuck':['Planning','Working'].includes(t.st)?'plan':'todo';
const projN=id=>(D.projects.find(p=>p.id===id)||{n:''}).n;
function myProjects(){return isAdm()?D.projects:D.projects.filter(p=>p.m.includes(S.me)||myTasks().some(t=>t.proj===p.id))}
function kCard(t,c){const late=t.st!=='Done'&&t.due<TODAY;return `<div class="kc" data-kid="${t.id}" data-a="tOpen" data-id="${t.id}" style="--kc:${c[2]}" role="button" tabindex="0"><b>${h(t.t)}</b><div class="kd ${late&&c[0]!=='done'?'late':''}">${ic('cal')}${fmt(t.due)}${t.pri==='High'?'<span class="kp">High</span>':''}${t.st==='Review'?'<span class="kr">Awaiting approval</span>':''}</div><div class="km">${h(projN(t.proj))}${isAdm()||t.by===S.me?` · ${h(nmF(t.o))}`:''}</div></div>`}
function kanban(){S.kp=S.kp||'all';S.kw=S.kw||'all';let T=myTasks();const PR=myProjects();
 const inP=t=>S.kp==='all'||t.proj===S.kp,inW=t=>S.kw==='all'||t.o===S.kw;
 const cntP=id=>T.filter(t=>(id==='all'||t.proj===id)&&t.st!=='Done').length;
 const people=isAdm()?STAFF:[S.me];
 T=T.filter(t=>inP(t)&&inW(t));
 return `<div class="kchips">${[['all','All projects'],...PR.map(p=>[p.id,p.n])].map(([id,n])=>`<button class="kchip ${S.kp===id?'on':''}" data-a="kp" data-t="${id}" ${id!=='all'?`data-pid="${id}"`:''}>${h(n)} <span>${cntP(id)}</span></button>`).join('')}</div>
 <div class="ktool"><label class="sr" for="kw">Person</label><select id="kw" data-ch="kw" class="ksel">${isAdm()?'<option value="all">👤 Everyone</option>':''}${people.map(k=>`<option value="${k}" ${S.kw===k?'selected':''}>👤 ${h(nmF(k))}</option>`).join('')}</select><span class="xs mut hide-m" style="flex:1">Drag a card to move it · click a card to open it · right-click a card for assignee, priority and project${isAdm()?' · right-click a project to set its members':''}</span>${isAdm()?`<button class="btn sm sec" data-a="projNew">${ic('plus')}Project</button>`:''}<button class="btn sm" data-a="tNew">${ic('plus')}Add task</button></div>
 <div class="kb">${KCOL.map(c=>{const L=T.filter(t=>colOf(t)===c[0]).sort((a,b)=>a.due.localeCompare(b.due));return `<div class="kcol" data-kcol="${c[0]}"><div class="kh"><i style="background:${c[2]}"></i><b>${c[1]}</b><span>${L.length}</span></div><div class="kl">${L.map(t=>kCard(t,c)).join('')||'<div class="kempty">Drop tasks here</div>'}</div></div>`}).join('')}</div>`}
function taskForms(){const PR=myProjects();return `<div class="card" style="max-width:640px"><b>Task request form</b><div class="xs mut">Fill this to raise a task. It lands in "To do" of the chosen project.</div>
 <label for="tf-t">Task</label><input id="tf-t" placeholder="e.g. Christmas landing page"><label for="tf-p">Project</label><select id="tf-p">${PR.map(p=>`<option value="${p.id}">${h(p.n)}</option>`).join('')}</select>
 <div class="grid g2"><div><label for="tf-o">Assign to</label><select id="tf-o">${(isAdm()?STAFF:[S.me]).map(k=>`<option value="${k}">${h(nmF(k))}</option>`).join('')}</select></div><div><label for="tf-d">Due date</label><input id="tf-d" type="date" value="${addD(TODAY,1)}"></div></div>
 <label>Priority</label>${opts('tf-pr',['Normal','High'],'Normal')}<label for="tf-x">Details</label><textarea id="tf-x" placeholder="What is expected?"></textarea><button class="btn w" style="margin-top:12px" data-a="tfSave">Submit</button></div>`}
A.tfSave=()=>{const t=val('tf-t');if(!t)return toast('Write the task');const p=val('tf-p');D.tasks.push({id:nid('k'),t,desc:val('tf-x'),o:val('tf-o')||S.me,co:'log',proj:p,due:val('tf-d')||addD(TODAY,1),pri:pick1('tf-pr')||'Normal',type:'One-time',tags:[],check:[],st:'To do',by:S.me});save();S.ttab='proj';S.kp=p;render();toast('Task added to '+projN(p))};
function timeline(){const T=myTasks().slice().sort((a,b)=>a.due.localeCompare(b.due));const days=[...new Set(T.map(t=>t.due))];
 return `<div class="tl">${days.map(d=>`<div class="tlg"><div class="tld ${d<TODAY?'past':d===TODAY?'now':''}">${d===TODAY?'Today':fmt(d)}</div><div>${T.filter(t=>t.due===d).map(t=>{const c=KCOL.find(x=>x[0]===colOf(t));return `<div class="tli" data-a="tOpen" data-id="${t.id}" role="button" tabindex="0" style="--kc:${c[2]}"><b>${h(t.t)}</b><span>${h(projN(t.proj))} · ${h(nmF(t.o))} · ${c[1]}</span></div>`}).join('')}</div></div>`).join('')||empty('No tasks')}</div>`}
const _vtasks=V.tasks;V.tasks=()=>{if(S.me==='nayan')return _vtasks();S.ttab=S.ttab||'proj';const me=ME()||{n:''};
 if(S.ttab==='cal'||S.ttab==='meet'){S.tv=S.ttab==='meet'?'meet':'cal';const inner=_vtasks();return taskHead(me)+inner.replace(/^[\s\S]*?<div style="margin:10px 0 12px">[\s\S]*?<\/div>/,'').replace(/<div class="fab">[\s\S]*$/,'')}
 return taskHead(me)+(S.ttab==='forms'?taskForms():S.ttab==='time'?timeline():kanban())};
function taskHead(me){return `<div class="tcrumb"><span class="mut">Tasks</span> / <b>${{proj:'Projects',forms:'Forms',cal:'Calendar',time:'Timeline',meet:'Meetings'}[S.ttab]}</b><span class="sp"></span><span class="tpill">${new Date().toLocaleDateString('en-IN',{weekday:'short',day:'numeric',month:'short',year:'numeric'})}</span><span class="tpill">${av(me.n)}<span><b>${h(nmF(S.me))}</b><small>${h(me.r||'')}</small></span></span></div><h1 class="ttl">Tasks</h1>
 <div class="ttabs">${[['proj','Projects'],['forms','Forms'],['cal','Calendar'],['time','Timeline'],...(isAdm()||['mohin','omadsul','himanshu'].includes(S.me)?[['meet','Meetings']]:[])].map(([k,n])=>`<button class="${S.ttab===k?'on':''}" data-a="ttab" data-t="${k}">${n}</button>`).join('')}</div>`}
A.ttab=e=>{S.ttab=e.dataset.t;render()};A.kp=e=>{S.kp=e.dataset.t;render()};
/* drag & drop (pointer based: works with mouse, touch and pen) */
let KD=null,KMOVED=false;
function kMove(id,k){const t=D.tasks.find(x=>x.id===id);if(!t||colOf(t)===k)return;const ns=k==='todo'?'To do':k==='plan'?'Planning':k==='stuck'?'Stuck':(canApprove(t)?'Done':'Review');t.st=ns;save();render();toast(ns==='Review'?'Sent for approval to '+nmF(t.by||'darshan'):'Moved to '+KCOL.find(c=>c[0]===k)[1])}
document.addEventListener('pointerdown',e=>{if(e.button!==0)return;const c=e.target.closest&&e.target.closest('[data-kid]');if(!c)return;KD={id:c.dataset.kid,el:c,x:e.clientX,y:e.clientY,g:null};KMOVED=false});
document.addEventListener('pointermove',e=>{if(!KD)return;const dx=e.clientX-KD.x,dy=e.clientY-KD.y;if(!KD.g&&Math.hypot(dx,dy)<8)return;
 if(!KD.g){const r=KD.el.getBoundingClientRect();KD.g=KD.el.cloneNode(true);Object.assign(KD.g.style,{position:'fixed',left:r.left+'px',top:r.top+'px',width:r.width+'px',zIndex:9999,pointerEvents:'none',transform:'rotate(2deg)',boxShadow:'0 12px 28px rgba(16,24,40,.25)',opacity:.95});KD.g.classList.add('ghost');document.body.appendChild(KD.g);KD.el.classList.add('drag');KD.ox=r.left;KD.oy=r.top;KMOVED=true}
 KD.g.style.left=(KD.ox+dx)+'px';KD.g.style.top=(KD.oy+dy)+'px';e.preventDefault();
 const col=document.elementFromPoint(e.clientX,e.clientY);const k=col&&col.closest&&col.closest('[data-kcol]');document.querySelectorAll('.kcol.over').forEach(x=>x!==k&&x.classList.remove('over'));if(k)k.classList.add('over')});
document.addEventListener('pointerup',e=>{if(!KD)return;const d=KD;KD=null;if(!d.g)return;d.g.remove();d.el.classList.remove('drag');document.querySelectorAll('.kcol.over').forEach(x=>x.classList.remove('over'));const col=document.elementFromPoint(e.clientX,e.clientY);const k=col&&col.closest&&col.closest('[data-kcol]');if(k)kMove(d.id,k.dataset.kcol)});
document.addEventListener('click',e=>{if(KMOVED){KMOVED=false;e.stopPropagation();e.preventDefault()}},true);
/* right-click: card → assignee/priority/project ; project chip → members */
document.addEventListener('contextmenu',e=>{const c=e.target.closest&&e.target.closest('[data-kid]');if(c){e.preventDefault();const t=D.tasks.find(x=>x.id===c.dataset.kid);if(!t)return;const can=isAdm()||t.by===S.me;
 sheet(`<h2>${h(t.t)}</h2>${can?`<label for="kq-o">Assignee</label><select id="kq-o">${STAFF.map(k=>`<option value="${k}" ${t.o===k?'selected':''}>${h(nmF(k))}</option>`).join('')}</select>`:''}<label>Priority</label>${opts('kq-p',['Normal','High'],t.pri==='High'?'High':'Normal')}<label for="kq-j">Project</label><select id="kq-j">${D.projects.map(p=>`<option value="${p.id}" ${t.proj===p.id?'selected':''}>${h(p.n)}</option>`).join('')}</select><label for="kq-t">Tags</label><input id="kq-t" value="${h((t.tags||[]).join(', '))}"><button class="btn w" style="margin-top:12px" data-a="kqSave" data-id="${t.id}">Save</button>`);return}
 const p=e.target.closest&&e.target.closest('[data-pid]');if(p&&isAdm()){e.preventDefault();A.projMem({dataset:{id:p.dataset.pid}})}});
A.kqSave=e=>{const t=D.tasks.find(x=>x.id===e.dataset.id);const o=val('kq-o');if(o)t.o=o;t.pri=pick1('kq-p')||t.pri;t.proj=val('kq-j')||t.proj;t.tags=val('kq-t').split(',').map(s=>s.trim()).filter(Boolean);save();closeM();render();toast('Task updated')};
A.projNew=()=>{if(!isAdm())return;sheet(`<h2>New project</h2><label for="pj-n">Project name</label><input id="pj-n" placeholder="e.g. Christmas campaign"><label>Members</label>${pickList('pj-m',[])}<button class="btn w" style="margin-top:12px" data-a="projSave">Create project</button>`)};
A.projSave=()=>{const n=val('pj-n');if(!n)return toast('Name the project');const id=nid('pj');D.projects.push({id,n,m:['darshan','nameera',...chkd('pj-m')]});save();closeM();S.kp=id;render();toast('Project created')};
A.projMem=e=>{const p=D.projects.find(x=>x.id===e.dataset.id);if(!p)return;sheet(`<h2>${h(p.n)} · members</h2><p class="mut sm">Only members (plus Darshan sir & Nameera) see this project.</p>${pickList('pm-m',p.m)}<button class="btn w" style="margin-top:12px" data-a="projMemSave" data-id="${p.id}">Save members</button>`)};
A.projMemSave=e=>{const p=D.projects.find(x=>x.id===e.dataset.id);p.m=[...new Set(['darshan','nameera',...chkd('pm-m')])];save();closeM();render();toast('Members saved')};
function pickList(id,sel){return `<div class="pickl" id="${id}">${STAFF.filter(k=>!['darshan','nameera'].includes(k)).map(k=>`<label><input type="checkbox" value="${k}" ${sel.includes(k)?'checked':''}> ${av(nm(k),'s')} ${h(nmF(k))} <span class="xs mut">${h(P[k].team||'')}</span></label>`).join('')}</div>`}
const chkd=id=>[...document.querySelectorAll('#'+id+' input:checked')].map(x=>x.value);
/* project in new-task form */
const _tf=taskForm;taskForm=function(d){d=d||{};const PR=myProjects();return _tf(d).replace('<label for="nck">',`<label for="npj">Project</label><select id="npj">${PR.map(p=>`<option value="${p.id}" ${(d.proj||S.kp)===p.id?'selected':''}>${h(p.n)}</option>`).join('')}</select><label for="nck">`)};
const _tc=A.tCreate;A.tCreate=e=>{const pj=val('npj'),n=D.tasks.length;_tc(e);if(D.tasks.length>n&&pj)D.tasks[D.tasks.length-1].proj=pj;save();render()};
/* change handler for person filter */
document.addEventListener('change',e=>{if(e.target&&e.target.dataset&&e.target.dataset.ch==='kw'){S.kw=e.target.value;render()}});

/* ---------- Overdue reminders: to the person AND whoever gave the task ---------- */
function overdueFor(k){return D.tasks.filter(t=>t.st!=='Done'&&t.due<TODAY&&(t.o===k||(t.by||'darshan')===k))}
function overdueNote(k){const L=overdueFor(k);if(!L.length)return '';return `<div class="latenote" style="margin-bottom:14px"><b>⏰ ${L.length} overdue task${L.length>1?'s':''}</b><div class="sm">${L.slice(0,4).map(t=>`${h(t.t)} — ${t.o===k?'yours':'given to '+h(nmF(t.o))}, due ${fmt(t.due)}`).join('<br>')}</div></div>`}
const _sh6=staffHome;staffHome=function(){return overdueNote(S.me)+_sh6()};

