if(!D.grpV2){const pune=STAFF.filter(k=>{const e=empOf(k);return !e||e.city!=='Goa'});
 const keep=D.groups.find(g=>g.id==='goa');
 D.groups=[{id:'ann',n:'Announcement',m:[...new Set(['darshan','nameera',...pune])],who:['darshan','nameera']},
 {id:'smm',n:'SMM',m:['darshan','nameera','swapnil','omparvate','himanshu']},
 {id:'acc',n:'Accounts',m:['darshan','nameera','snehalz']},
 {id:'wh',n:'Warehouse team',m:['darshan','nameera','zubair','abrar','mustafa','samadhan','shubham']},
 {id:'hrt',n:'HR',m:['darshan','nameera','snehalb']},
 {id:'cse',n:'CSE',m:['darshan','nameera','neetu','balaji','imran']},
 {id:'ops',n:'Ops Logistics',m:['darshan','nameera','mohin','omadsul']},...(keep?[Object.assign(keep,{n:'GovaaBazaar · Goa'})]:[])];
 D.msgs.forEach(m=>{if(m.g==='mkt')m.g='smm'});D.grpV2=1;save()}
const myGroups=()=>D.groups.filter(g=>isAdm()||(g.m||[]).includes(S.me));
const unreadG=g=>Math.max(0,D.msgs.filter(m=>m.g===g.id).length-((g.seen||{})[S.me]||0));
function chatHead(){const G=myGroups(),waN=D.wa.filter(c=>myWaTeams().includes(c.team)&&c.unread).length;
 return page('Chat','Groups · WhatsApp · Email')+`<div class="gbar">${G.map(g=>`<button class="${S.chm==='team'&&S.chat===g.id?'on':''}" data-a="chatGo" data-id="${g.id}">${h(g.n)}${unreadG(g)?`<span class="n">${unreadG(g)}</span>`:''}</button>`).join('')}<span class="gsep"></span><button class="${S.chm==='wa'?'on':''}" data-a="chm" data-t="wa">WhatsApp${waN?`<span class="n">${waN}</span>`:''}</button><button class="${S.chm==='email'?'on':''}" data-a="chm" data-t="email">Email</button>${isAdm()?`<button class="gadd" data-a="grpNew">${ic('plus')}Group</button>`:''}</div>`}
A.chatGo=e=>{S.chm='team';S.chat=e.dataset.id;render();setTimeout(()=>{const t=document.getElementById('thr');if(t)t.scrollTop=t.scrollHeight},30)};
const _vchat=V.chat;V.chat=()=>{const G=myGroups();if(S.chm==='team'||!S.chm){S.chm='team';if(!S.chat||!G.some(g=>g.id===S.chat))S.chat=G[0]?G[0].id:null;if(!S.chat)return chatHead()+empty('No groups yet')}
 let out=_vchat();
 if(S.chm==='team'){const g=D.groups.find(x=>x.id===S.chat);out=out.replace(/<button class="cb" data-a="chatX"[^>]*>[\s\S]*?<\/button>/,'');
  if(g&&isAdm())out=out.replace('</div><div class="thread wa"',`<button class="gmem" data-a="grpMem" data-id="${g.id}">${ic('users')} Members · ${(g.m||[]).length}</button></div><div class="thread wa"`);
  return chatHead()+out}
 if(out.startsWith('<div class="row nw" style="margin-bottom:14px"><div style="flex:1"><h1>Chat</h1>'))out=out.replace(/^[\s\S]*?<div class="chips" role="tablist">[\s\S]*?<\/div>/,'');return chatHead()+out};
A.grpMem=e=>{if(!isAdm())return;const g=D.groups.find(x=>x.id===e.dataset.id);sheet(`<h2>${h(g.n)} · members</h2><p class="mut sm">Only members can see and open this group. Darshan sir and Nameera always have access.</p>${pickList('gm-m',g.m||[])}<button class="btn w" style="margin-top:12px" data-a="grpMemSave" data-id="${g.id}">Save members</button>`)};
A.grpMemSave=e=>{const g=D.groups.find(x=>x.id===e.dataset.id);g.m=[...new Set(['darshan','nameera',...chkd('gm-m')])];save();closeM();render();toast('Members saved')};
A.grpNew=()=>{if(!isAdm())return;sheet(`<h2>New group</h2><label for="gn2">Group name</label><input id="gn2" placeholder="e.g. Christmas campaign"><label>Members</label>${pickList('gn-m',[])}<button class="btn w" style="margin-top:12px" data-a="grpSave2">Create group</button>`)};
A.grpSave2=()=>{const n=val('gn2');if(!n)return toast('Name the group');const id=nid('g');D.groups.push({id,n,m:['darshan','nameera',...chkd('gn-m')]});save();closeM();S.chm='team';S.chat=id;render();toast('Group created')};

/* ---------- Dashboard: Milestones panel ---------- */
if(!D.coPct)D.coPct={gb:0,log:0,hr:0,jup:0,studios:0};
const MSCO=[['gb','GovaaBazaar'],['log','Logistics'],['hr','HR Consultancy'],['jup','Jupiter'],['studios','JDAC Studios']];
milestone=function(){const left=daysTo('2026-11-30'),can=isAdm(),T=D.targets,hits=T.filter(t=>pct(t.v,t.goal)>=100).length,overall=T.length?Math.round(T.reduce((a,t)=>a+Math.min(100,pct(t.v,t.goal)),0)/T.length):0;
 return `<div class="mspanel"><div class="msl"><div class="row nw"><h2 style="flex:1">Milestones</h2><span class="pill">Milestone 1 · ${left>=0?left+' days left':'ended'}</span>${can?`<button class="lnk" data-a="tEdit">Edit</button>`:''}</div>
 <div class="msscore"><div><b>${hits}<small>/${T.length}</small></b><span>targets hit today</span></div><div><b>${overall}%</b><span>of today's milestone overall</span></div></div>
 <div class="mslist">${T.map(t=>{const p=Math.min(100,pct(t.v,t.goal));return `<div class="msr"><div class="tx"><b>${h(t.l)}</b><span>${coShort(t.co)} · ${h(nmF(t.who))} · per ${t.per}</span><div class="msbar"><i style="width:${p}%;background:${p>=100?'var(--g)':p>=50?'#24408E':'#E8A33D'}"></i></div></div><div class="step"><button data-a="tStep" data-id="${t.id}" data-n="-1" aria-label="Less">−</button><span>${t.unit==='₹'?(t.v/1000).toFixed(1)+'k':t.v}/${t.unit==='₹'?(t.goal/1000)+'k':t.goal}</span><button data-a="tStep" data-id="${t.id}" data-n="1" aria-label="More">+</button></div></div>`}).join('')}</div></div>
 <div class="msr2"><b class="msh">Company progress</b>${MSCO.map(([k,n])=>{const v=+D.coPct[k]||0;return `<div class="mco"><div class="row nw"><span class="cdot" style="background:${(CO[k]||{}).c||'#999'}"></span><b style="flex:1">${n}</b>${can?`<input class="mcin" type="number" min="0" max="100" value="${v}" data-ch="coPct" data-k="${k}" aria-label="${n} progress %">%`:`<b>${v}%</b>`}</div><div class="msbar"><i style="width:${v}%;background:${(CO[k]||{}).c||'#24408E'}"></i></div></div>`}).join('')}<div class="xs mut" style="margin-top:6px">${can?'Type a % — the bar updates instantly.':'Updated by Darshan sir & Nameera.'}</div></div></div>`};
