function taskCal(){const T=myTasks().filter(t=>(S.kp||'all')==='all'||t.proj===S.kp);const m=S.tcm||monStart(TODAY),first=(new Date(m+'T12:00:00').getDay()+6)%7,en=monEnd(m);let cells='';for(let i=0;i<first;i++)cells+='<div class="tcx out"></div>';
 for(let d=m;d<=en;d=addD(d,1)){const L=T.filter(t=>t.due===d);cells+=`<div class="tcx ${d===TODAY?'td':''} ${d<TODAY?'past':''}"><div class="tcd">${+d.slice(8)}</div>${L.slice(0,4).map(t=>{const c=KCOL.find(x=>x[0]===colOf(t));return `<button class="tcc" style="--kc:${c[2]}" data-a="tOpen" data-id="${t.id}" title="${h(t.t)} · ${h(nmF(t.o))} · ${c[1]}">${h(t.t)}</button>`}).join('')}${L.length>4?`<div class="xs mut">+${L.length-4} more</div>`:''}</div>`}
 const lbl=new Date(m+'T12:00:00').toLocaleDateString('en-IN',{month:'long',year:'numeric'});
 return `<div class="row" style="margin-bottom:10px"><button class="btn sm sec" data-a="tcm" data-n="-1" aria-label="Previous month">${ic('back')}</button><b style="min-width:160px;text-align:center">${lbl}</b><button class="btn sm sec" data-a="tcm" data-n="1" aria-label="Next month">${ic('right')}</button><button class="lnk" data-a="tcm" data-n="0">This month</button><span class="sp"></span>${KCOL.map(c=>`<span class="xs" style="display:inline-flex;align-items:center;gap:4px;margin-left:8px"><i style="width:9px;height:9px;border-radius:50%;background:${c[2]};display:inline-block"></i>${c[1]}</span>`).join('')}</div>
 <div class="tcal">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(x=>`<div class="tch">${x}</div>`).join('')}${cells}</div>`}
