function taskGantt(){const T=myTasks().filter(t=>(S.kp||'all')==='all'||t.proj===S.kp);const s=wkStart(addD(TODAY,-7)),N=35,days=Array.from({length:N},(_,i)=>addD(s,i)),idx=d=>Math.max(0,Math.min(N-1,Math.round((new Date(d+'T12:00:00')-new Date(s+'T12:00:00'))/864e5)));
 const groups=D.projects.filter(p=>T.some(t=>t.proj===p.id));
 return `<div class="gantt"><div class="gh"><div class="gl">Task</div><div class="gg" style="--n:${N}">${days.map(d=>{const x=new Date(d+'T12:00:00');return `<div class="${d===TODAY?'now':''} ${x.getDay()===0?'sun':''}">${x.getDay()===1||d===s?`<b>${x.getDate()} ${x.toLocaleDateString('en-IN',{month:'short'})}</b>`:x.getDate()}</div>`}).join('')}</div></div>
 ${groups.map(p=>`<div class="gp">${h(p.n)}</div>${T.filter(t=>t.proj===p.id).sort((a,b)=>a.due.localeCompare(b.due)).map(t=>{const c=KCOL.find(x=>x[0]===colOf(t)),st=t.start||addD(t.due,-(t.pri==='High'?4:2)),a=idx(st),b=idx(t.due);return `<div class="gr"><div class="gl"><button data-a="tOpen" data-id="${t.id}"><b>${h(t.t)}</b><span>${h(nmF(t.o))} · ${c[1]}</span></button></div><div class="gg" style="--n:${N}"><div class="gb" style="grid-column:${a+1}/${b+2};background:${c[2]}" title="${fmt(st)} → ${fmt(t.due)}">${fmt(t.due)}</div><i class="gtoday" style="grid-column:${idx(TODAY)+1}"></i></div></div>`}).join('')}`).join('')||empty('No tasks')}</div>
 <div class="xs mut" style="margin-top:6px">Bars run from the start date to the due date · colours show To do / Planning / Stuck / Completed · the line is today.</div>`}
