/* HR Consultancy: "Employer" → "Client" */
const _vco2=V.co;V.co=()=>{const o=_vco2();return S.co==='hr'?o.replace(/Employers ↔/g,'Clients ↔').replace(/Employer CRM/g,'Client CRM').replace(/>Employers</g,'>Clients<').replace(/EMPLOYERS/g,'CLIENTS').replace(/Add employer/g,'Add client').replace(/Employer side/g,'Client side').replace(/employer lead/g,'client lead').replace(/Convert to employer/g,'Convert to client').replace(/EMPLOYER OFFER/g,'CLIENT OFFER').replace(/Employer logins/g,'Client logins').replace(/Every employer/g,'Every client').replace(/>Employers ·/g,'>Clients ·'):o};
CTABS.hr=CTABS.hr.map(x=>x[0]==='ecrm'?['ecrm','Client CRM']:x[0]==='emp'?['emp','Clients']:x);
/* ===== HR Consultancy v2: two teams — CLIENTS (Client CRM → Clients → Jobs) and JOB SEEKERS (one funnel → Employees) ===== */
CTABS.hr=[['hire','Dashboard'],['ecrm','Client CRM'],['emp','Clients'],['jobs','Jobs'],['seek','Job seekers'],['placed','Employees']];
const JSTG=[['New lead','#8A93A3'],['Called','#2F6BE0'],['Registered','#0B6E8A'],['Shared with client','#7A2E8E'],['Interview','#E8A33D'],['Selected','#1F9D55'],['Not interested','#E03A3E']];
function seekItems(){const R=[];HR.SL.filter(l=>!l.conv).forEach(l=>R.push({k:'lead',id:l.id,n:l.n,sub:l.want,city:l.city,src:l.src,own:l.own,next:l.next,col:l.st==='Not interested'?'Not interested':l.st==='New'?'New lead':'Called'}));
 HR.P.forEach(p=>{const L=HR.L.filter(l=>l.p===p.id);if(L.some(l=>['Joined','Completed'].includes(l.st)))return;const a=L.find(l=>!['Rejected','Left'].includes(l.st));const col=!a?'Registered':['Applied','Shortlisted','Shared'].includes(a.st)?'Shared with client':a.st==='Interview'?'Interview':a.st==='Selected'?'Selected':'Registered';R.push({k:'cand',id:p.id,l:a&&a.id,n:p.n,sub:a?(hJ(a.j).role||'')+' · '+(hC(a.co).n||''):p.head.split(' · ')[0],city:p.city,src:a?a.st:'Profile + login',own:'snehalb',col})});return R}
CP['hr:seek']=()=>{const R=seekItems(),q=(S.crq||'').toLowerCase(),F=R.filter(x=>!q||(x.n+' '+x.sub+' '+x.city).toLowerCase().includes(q));
 return `<div class="row" style="margin-bottom:10px"><div class="search" style="flex:1;margin:0"><span aria-hidden="true">${ic('search')}</span><label class="sr" for="crq">Search job seekers</label><input id="crq" data-in="crq" value="${h(S.crq||'')}" placeholder="Search name, job, city…"></div><button class="btn sm sec" data-a="hrLeadNew" data-k="s">${ic('plus')}Add lead</button><button class="btn sm" data-a="hrPNew">${ic('plus')}Register job seeker</button></div>
 <div class="xs mut" style="margin-bottom:8px">One funnel for every job seeker: Facebook/Instagram leads land in <b>New lead</b> → call → register (profile + login) → share with a client → interview → selected. When they join, they move to <b>Employees</b>.</div>
 <div class="kb crm" style="grid-template-columns:repeat(${JSTG.length},minmax(180px,1fr))">${JSTG.map(([s,c])=>{const C=F.filter(x=>x.col===s);return `<div class="kcol" style="min-height:0"><div class="kh"><i style="background:${c}"></i><b>${s}</b><span>${C.length}</span></div><div class="kl">${C.map(x=>`<button class="kc" style="--kc:${c};cursor:pointer" ${x.k==='lead'?`data-a="hrLeadOpen" data-k="s" data-id="${x.id}"`:`data-a="hrCand" data-id="${x.id}" ${x.l?`data-l="${x.l}"`:''}`}><b>${h(x.n)}</b><div class="kd" style="color:var(--mut)">${h(x.sub||'')} · ${h(x.city||'')}</div><div class="km">${h(x.src||'')}${x.next?' · follow-up '+fmt(x.next):''}</div></button>`).join('')||'<div class="kempty">—</div>'}</div></div>`}).join('')}</div>`};
/* Jobs: company-wise */
CP['hr:jobs']=()=>{const C=HR.C.filter(c=>HR.J.some(j=>j.co===c.id));S.jco=S.jco||'all';const J=HR.J.filter(j=>S.jco==='all'||j.co===S.jco);
 return `<div class="kchips"><button class="kchip ${S.jco==='all'?'on':''}" data-a="jco" data-t="all">All clients <span>${HR.J.length}</span></button>${C.map(c=>`<button class="kchip ${S.jco===c.id?'on':''}" data-a="jco" data-t="${c.id}">${h(c.n)} <span>${HR.J.filter(j=>j.co===c.id).length}</span></button>`).join('')}</div>
 ${C.filter(c=>S.jco==='all'||c.id===S.jco).map(c=>`<div class="card" style="margin-bottom:12px"><div class="row nw">${av(c.n)}<b style="flex:1">${h(c.n)}</b><span class="xs mut">${HR.J.filter(j=>j.co===c.id).reduce((a,j)=>a+j.open,0)} openings</span><button class="btn sm sec" data-a="hrClient" data-id="${c.id}">Open client</button></div><div class="list" style="margin:8px 0 0;box-shadow:none">${J.filter(j=>j.co===c.id).map(j=>{const f=HR.L.filter(l=>l.j===j.id&&['Joined','Completed'].includes(l.st)).length,pr=HR.L.filter(l=>l.j===j.id&&!['Joined','Completed','Rejected','Left'].includes(l.st)).length;return `<div class="li"><div class="tx"><b>${h(j.role)}</b><div class="m">${h(j.city)} · ${inr(j.smin)}–${inr(j.smax)}/month</div><div class="bar g" style="margin-top:5px"><i style="width:${pct(f,j.open)}%"></i></div></div><div style="text-align:right"><b class="num">${f}/${j.open} filled</b><div class="xs mut">${pr} in process</div></div>${pill(f>=j.open?'Closed':'Open',f>=j.open?'':'g')}</div>`}).join('')}</div></div>`).join('')}`};
A.jco=e=>{S.jco=e.dataset.t;render()};
/* Clients list: one row per client → full client page (overview, jobs, billing & MIS, fee settings, wallet, login) */
CP['hr:emp']=()=>`<div class="row" style="margin-bottom:12px"><span class="sm mut" style="flex:1">${HR.C.filter(c=>!c.internal).length} clients · onboarded from the Client CRM</span><button class="btn sm" data-a="hrCoNew">${ic('plus')}Add client · creates their login</button></div>
 <div class="xsheet"><table><thead><tr><th class="stk">Client</th><th>City</th><th>Industry</th><th class="n">Jobs</th><th class="n">Employees</th><th>Fee</th><th class="n">Wallet</th><th>Login</th><th></th></tr></thead><tbody>${HR.C.filter(c=>!c.internal).map(c=>`<tr class="tap" data-a="hrClient" data-id="${c.id}" style="cursor:pointer"><td class="stk"><div class="row nw" style="gap:8px">${av(c.n)}<b>${h(c.n)}</b>${c.group?'<span class="pill b" style="font-size:10.5px">JDAC group</span>':''}</div></td><td>${h(c.city)}</td><td>${h(c.ind)}</td><td class="n">${HR.J.filter(j=>j.co===c.id).length}</td><td class="n">${HR.L.filter(l=>l.co===c.id&&l.st==='Joined').length}</td><td>${c.plan.fee}% · D${c.plan.a}+D${c.plan.b}</td><td class="n">${inr(c.wallet||0)}</td><td>${pill(c.login,c.login==='Active'?'g':'a')}</td><td><button class="btn sm sec" data-a="hrClient" data-id="${c.id}">Open</button></td></tr>`).join('')}</tbody></table></div>`;
A.hrClient=e=>{S.hcid=e.dataset.id;S.hct=e.dataset.t||S.hct||'over';const c=hC(S.hcid);if(!c.id)return;const tabs=[['over','Overview'],['jobs','Jobs'],['bill','Billing & MIS'],['fee','Fee settings'],['wal','Wallet'],['login','Login']];
 const body={over:()=>`<div class="grid g2"><div class="card"><div class="xs mut">Contact</div><b>${h(c.contact)} · ${h(c.mob)}</b><div class="xs mut" style="margin-top:6px">Industry</div><b>${h(c.ind)} · ${h(c.city)}</b><div class="xs mut" style="margin-top:6px">With us since</div><b>${fmt(c.since)}</b></div><div class="card"><div class="xs mut">KYC</div><b>${h(c.kyc)}</b><div class="xs mut" style="margin-top:6px">JDAC trust score</div><b>${c.trust}/100</b><div class="xs mut" style="margin-top:6px">Rating</div><b>${c.rating||'—'}</b></div></div>`,
  jobs:()=>`<div class="list">${HR.J.filter(j=>j.co===c.id).map(j=>{const f=HR.L.filter(l=>l.j===j.id&&['Joined','Completed'].includes(l.st)).length;return `<div class="li"><div class="tx"><b>${h(j.role)}</b><div class="m">${h(j.city)} · ${inr(j.smin)}–${inr(j.smax)}</div></div><b class="num">${f}/${j.open}</b></div>`}).join('')||empty('No jobs posted yet')}</div>`,
  bill:()=>hrBillHTML(c.id,false),
  fee:()=>`<label>Hiring fee (% of one month salary)</label>${opts('cf-fee',['0','50','75','100'],String(c.plan.fee))}<div class="grid g2"><div><label for="cf-a">1st half due on day</label><input id="cf-a" type="number" value="${c.plan.a}"></div><div><label for="cf-b">2nd half due on day</label><input id="cf-b" type="number" value="${c.plan.b}"></div></div><div class="xs mut" style="margin-top:6px">50/50 split · no replacement. Set this when the client is onboarded.</div>${isAdm()?`<button class="btn w" style="margin-top:12px" data-a="cfSave" data-id="${c.id}">Save fee settings</button>`:''}`,
  wal:()=>`<div class="stats"><div><b>${inr(c.wallet||0)}</b><span>wallet balance</span></div><div><b>${inr(hrBill(c.id).filter(r=>r.st==='Due').reduce((a,r)=>a+r.tot,0))}</b><span>due now</span></div></div><div class="list">${(HR.walletLog||[]).filter(w=>w.co===c.id).map(w=>`<div class="li"><div class="tx"><b>${h(w.t)}</b><div class="m">${fmt(w.d)}</div></div><b class="amt" style="color:${w.amt<0?'var(--r)':'var(--g)'}">${w.amt<0?'−':'+'}${inr(Math.abs(w.amt))}</b></div>`).join('')||empty('No wallet activity')}</div><div class="note">Offer: recharge up to ₹10,000 and get 100% cashback, usable only for hiring fees.</div>`,
  login:()=>`<div class="list"><div class="li"><div class="tx"><div class="m">Login ID</div><b>${h(c.email)}</b></div>${pill(c.login,c.login==='Active'?'g':'a')}</div><div class="li"><div class="tx"><div class="m">Company code</div><b>JDAC-HRC-${c.id.slice(1).padStart(4,'0')}</b></div></div><div class="li"><div class="tx"><div class="m">Last login</div><b>${c.last?fmt(c.last):'—'}</b></div></div></div><div class="row" style="margin-top:10px"><button class="btn sm sec" data-a="toast" data-t="Reset link sent to ${h(c.email)}">Reset password</button>${c.login==='Active'?`<button class="btn sm" data-a="empPanel" data-id="${c.id}">${ic('eye')}Open their panel</button>`:''}</div>`}[S.hct]||(()=>'');
 sheet(`<div class="row nw">${av(c.n,'l')}<div style="flex:1"><h2>${h(c.n)}</h2><div class="xs mut">${h(c.ind)} · ${h(c.city)} · fee ${c.plan.fee}%</div></div>${c.login==='Active'?`<button class="btn sm sec" data-a="empPanel" data-id="${c.id}">${ic('eye')}Open their panel</button>`:''}</div><div class="kchips" style="margin-top:12px">${tabs.map(([k,n])=>`<button class="kchip ${S.hct===k?'on':''}" data-a="hrClient" data-id="${c.id}" data-t="${k}">${n}</button>`).join('')}</div><div style="margin-top:10px">${body()}</div><div class="xsheet" style="display:none"></div>`)};
