A.waNew=()=>{const T=myWaTeams();sheet(`<h2>New WhatsApp chat</h2><label for="wnn">Customer name</label><input id="wnn" placeholder="Name"><label for="wnp">WhatsApp number</label><input id="wnp" inputmode="tel" placeholder="98xxx xxxxx">${T.length>1?`<label for="wnt">Send from</label><select id="wnt">${T.map(k=>`<option value="${k}" ${(S.wat||T[0])===k?'selected':''}>${h(WATEAM[k])}</option>`).join('')}</select>`:''}<label for="wnm">First message · approved template</label><select id="wnm">${D.waTpl.map((t,i)=>`<option value="${i}">${h(t[0])}</option>`).join('')}</select><p class="xs mut">WhatsApp only allows approved templates when you start a chat. Free text works after the customer replies.</p><button class="btn w" style="margin-top:12px" data-a="waNewGo">Start chat</button>`)};
