 <div class="xsheet"><table><thead><tr><th class="stk">Client</th><th class="n">Placements</th><th class="n">Fee</th><th class="n">Invoices</th><th class="n">Billed</th><th class="n">GST</th><th class="n">Total</th><th class="n">Collected</th><th class="n">Overdue</th><th class="n">Upcoming</th><th class="n">Wallet</th><th></th></tr></thead><tbody>${Sm.map(b=>`<tr><td class="stk"><b>${h(b.c.n)}</b><span>${b.c.internal?'JDAC group':h(b.c.city||'Client')}</span></td><td class="n">${b.ppl.size}</td><td class="n">${b.c.plan.fee}%</td><td class="n">${b.n}</td><td class="n">${inr(b.base)}</td><td class="n">${inr(b.gst)}</td><td class="n"><b>${inr(b.tot)}</b></td><td class="n" style="color:var(--g)">${inr(b.paid)}</td><td class="n" style="color:${b.due?'var(--r)':'inherit'}">${inr(b.due)}</td><td class="n">${inr(b.up)}</td><td class="n">${inr(b.c.wallet||0)}</td><td><button class="lnk" data-a="hrBill" data-id="${b.c.id}">Open</button></td></tr>`).join('')||`<tr><td colspan="12">${empty('No billing in this period')}</td></tr>`}${Sm.length?`<tr class="mistot"><td class="stk"><b>Total</b></td><td class="n">${Sm.reduce((a,b)=>a+b.ppl.size,0)}</td><td></td><td class="n">${R.length}</td><td class="n">${inr(t('base'))}</td><td class="n">${inr(t('gst'))}</td><td class="n">${inr(t('tot'))}</td><td class="n">${inr(t('paid'))}</td><td class="n">${inr(t('due'))}</td><td class="n">${inr(t('up'))}</td><td class="n">${inr(Sm.reduce((a,b)=>a+(b.c.wallet||0),0))}</td><td></td></tr>`:''}</tbody></table></div>
